-- State transitions declared for EmailVerificationToken (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.email_verification_tokens_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('pending', 'expired'), ('pending', 'revoked'), ('pending', 'verified'), ('verified', 'expired'), ('verified', 'revoked'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: email_verification_tokens.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS email_verification_tokens_status_transition_check ON sapiens.email_verification_tokens;
CREATE TRIGGER email_verification_tokens_status_transition_check
    BEFORE UPDATE OF "status" ON sapiens.email_verification_tokens
    FOR EACH ROW EXECUTE FUNCTION sapiens.email_verification_tokens_status_transition_check();
